import datetime as dt
import json
import sqlite3
from decimal import Decimal
from pathlib import Path
from feedsync import store

events = sorted((json.loads(line) for path in sorted(Path('dev/feed_data').glob('changes*.jsonl'))
                 for line in path.read_text().splitlines() if line.strip()), key=lambda e:e['seq'])
expected = {}
for e in events:
 if e['op']=='delete': expected.pop(e['sku'],None)
 else: expected[e['sku']] = (e['title'],int(Decimal(e['price'])*100),e['currency'],e.get('updated_at'),e['seq'])
c = sqlite3.connect('data/catalog.db'); c.row_factory=sqlite3.Row
actual = {r['sku']:(r['title'],r['price_cents'],r['currency'],r['updated_at'],r['feed_seq']) for r in c.execute('SELECT * FROM products')}
assert actual==expected, (actual,expected)
assert c.execute('SELECT count(*) FROM products').fetchone()[0]==len(expected)
assert c.execute('PRAGMA integrity_check').fetchone()[0]=='ok'
b = sqlite3.connect('/var/tmp/feedsync-before-v2-fix.db'); b.row_factory=sqlite3.Row
before = {r['id']:dict(r) for r in b.execute('SELECT * FROM price_overrides')}
expected_overrides = {k:dict(v) for k,v in before.items()}
for e in events:
 if e['op']!='delete': continue
 day=e['updated_at'][:10]
 for row in expected_overrides.values():
  if row['sku']==e['sku'] and row['starts_on']<=day and (row['ends_on'] is None or row['ends_on']>=day):
   row['ends_on']=(dt.date.fromisoformat(day)-dt.timedelta(days=1)).isoformat()
after = {r['id']:dict(r) for r in c.execute('SELECT * FROM price_overrides')}
assert after==expected_overrides
print('Validated all columns for',len(expected),'unique products against all',len(events),'feed events.')
print('Preserved all',len(after),'override audit rows. Changed only:')
for key in before:
 if before[key]!=after[key]: print(after[key]['sku'], 'ends_on:',before[key]['ends_on'],'->',after[key]['ends_on'])
assert c.execute("SELECT sql FROM sqlite_master WHERE name='merch_guard_active_override'").fetchone()[0]==b.execute("SELECT sql FROM sqlite_master WHERE name='merch_guard_active_override'").fetchone()[0]
print('Deletion guard unchanged; integrity_check: ok')
report_conn = store.connect('data/catalog.db')
rows=store.report_rows(report_conn)
today=dt.date.today().isoformat()
for row in rows:
 active=[o for o in after.values() if o['sku']==row['sku'] and o['starts_on']<=today and (o['ends_on'] is None or o['ends_on']>=today)]
 active.sort(key=lambda o:(o['starts_on'],o['id']),reverse=True)
 cents=active[0]['override_cents'] if active else expected[row['sku']][1]
 assert row['effective_price']==f'{cents//100}.{cents%100:02d}'
 assert row['source']==('override' if active else 'feed')
print('Independently validated every effective report price.')
print('Stored cursor:',store.get_state(report_conn,'feed_cursor'))
print('Feed requests so far:')
for line in Path('/var/tmp/feedstub/requests.log').read_text().splitlines():
 r=json.loads(line)
 if r['path']=='/v2/changes': print({k:r[k] for k in ['cursor','status','items','tombstones','next_cursor','has_more','ack']})
